using System; using System.Data.Entity; using System.Threading.Tasks; using OrderFlow.MVC.Data; using OrderFlow.MVC.Models; using OrderFlow.MVC.ViewModels;
namespace OrderFlow.MVC.Services { public class InventoryService { private readonly OrderFlowDbContext _db; public InventoryService(OrderFlowDbContext db) { _db = db; } public async Task<InventoryAvailabilityViewModel> GetAvailabilityAsync(int productId) { var item = await _db.Inventory.Include(i => i.Product).SingleOrDefaultAsync(i => i.ProductId == productId); if (item == null) return null; return new InventoryAvailabilityViewModel { ProductId = productId, Sku = item.Product.Sku, Name = item.Product.Name, QuantityOnHand = item.QuantityOnHand, ReservedQuantity = item.ReservedQuantity, AvailableQuantity = item.AvailableQuantity, ReorderLevel = item.Product.ReorderLevel, IsLowStock = item.AvailableQuantity <= item.Product.ReorderLevel }; } public async Task AdjustAsync(int productId, int delta, InventoryTransactionType type, string notes, int userId, int? orderId = null) { var inventory = await _db.Inventory.SingleOrDefaultAsync(i => i.ProductId == productId); if (inventory == null) throw new InvalidOperationException("Inventory record was not found."); if (inventory.QuantityOnHand + delta < 0) throw new InvalidOperationException("This adjustment would make stock negative."); var before = inventory.QuantityOnHand; inventory.QuantityOnHand += delta; inventory.UpdatedAtUtc = DateTime.UtcNow; _db.InventoryTransactions.Add(new InventoryTransaction { ProductId = productId, OrderId = orderId, PerformedByUserId = userId, Type = type, QuantityDelta = delta, QuantityBefore = before, QuantityAfter = inventory.QuantityOnHand, Notes = notes }); await _db.SaveChangesAsync(); } public async Task ReserveAsync(int productId, int quantity, int userId, int orderId) { var inventory = await _db.Inventory.SingleOrDefaultAsync(i => i.ProductId == productId); if (inventory == null || inventory.AvailableQuantity < quantity) throw new InvalidOperationException("Insufficient available inventory."); inventory.ReservedQuantity += quantity; inventory.UpdatedAtUtc = DateTime.UtcNow; _db.InventoryTransactions.Add(new InventoryTransaction { ProductId = productId, OrderId = orderId, PerformedByUserId = userId, Type = InventoryTransactionType.Reservation, QuantityDelta = 0, QuantityBefore = inventory.QuantityOnHand, QuantityAfter = inventory.QuantityOnHand, Notes = "Reserved for order fulfilment." }); } public async Task CommitStockOutAsync(int productId, int quantity, int userId, int orderId) { var inventory = await _db.Inventory.SingleOrDefaultAsync(i => i.ProductId == productId); if (inventory == null || inventory.ReservedQuantity < quantity || inventory.QuantityOnHand < quantity) throw new InvalidOperationException("Stock reservation is invalid."); var before = inventory.QuantityOnHand; inventory.QuantityOnHand -= quantity; inventory.ReservedQuantity -= quantity; inventory.UpdatedAtUtc = DateTime.UtcNow; _db.InventoryTransactions.Add(new InventoryTransaction { ProductId = productId, OrderId = orderId, PerformedByUserId = userId, Type = InventoryTransactionType.StockOut, QuantityDelta = -quantity, QuantityBefore = before, QuantityAfter = inventory.QuantityOnHand, Notes = "Shipped against order." }); } } }

